import { Link, useLocation } from "wouter";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { z } from "zod";
import { GraduationCap, BookOpen, FlaskConical, Shield, BarChart3 } from "lucide-react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Form, FormControl, FormField, FormItem, FormLabel, FormMessage } from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { useAuth } from "@/hooks/use-auth";
import { useToast } from "@/hooks/use-toast";

const registerSchema = z.object({
  fullName: z.string().min(2, "Full name must be at least 2 characters"),
  email: z.string().email("Please enter a valid email address"),
  username: z.string().min(3, "Username must be at least 3 characters").regex(/^[a-zA-Z0-9_]+$/, "Username can only contain letters, numbers, and underscores"),
  password: z.string().min(6, "Password must be at least 6 characters"),
  confirmPassword: z.string(),
}).refine((data) => data.password === data.confirmPassword, {
  message: "Passwords do not match",
  path: ["confirmPassword"],
});

type RegisterForm = z.infer<typeof registerSchema>;

const features = [
  { icon: BookOpen, title: "Document Analysis", description: "AI-powered review of academic papers" },
  { icon: FlaskConical, title: "Multi-Engine Analysis", description: "Six specialized analysis engines" },
  { icon: Shield, title: "Defense Simulation", description: "Practice your dissertation defense" },
  { icon: BarChart3, title: "Scoring & Insights", description: "Detailed scoring and feedback" },
];

export default function RegisterPage() {
  const { register, registerPending } = useAuth();
  const { toast } = useToast();
  const [, setLocation] = useLocation();

  const form = useForm<RegisterForm>({
    resolver: zodResolver(registerSchema),
    defaultValues: { fullName: "", email: "", username: "", password: "", confirmPassword: "" },
  });

  const onSubmit = async (data: RegisterForm) => {
    try {
      await register({
        fullName: data.fullName,
        email: data.email,
        username: data.username,
        password: data.password,
      });
      setLocation("/");
    } catch (error: any) {
      toast({
        title: "Registration Failed",
        description: error.message || "Could not create account",
        variant: "destructive",
      });
    }
  };

  return (
    <div className="flex min-h-screen" data-testid="page-register">
      <div className="hidden lg:flex lg:w-1/2 bg-primary flex-col justify-center p-12">
        <div className="max-w-md mx-auto">
          <div className="flex items-center gap-3 mb-8">
            <div className="flex items-center justify-center w-12 h-12 rounded-md bg-primary-foreground/20">
              <GraduationCap className="h-8 w-8 text-primary-foreground" />
            </div>
            <div>
              <h1 className="text-2xl font-bold text-primary-foreground">RavPaper Tutor</h1>
              <p className="text-sm text-primary-foreground/80">AI-Powered Academic Intelligence</p>
            </div>
          </div>
          <p className="text-lg text-primary-foreground/90 mb-8">
            Join thousands of researchers using AI to improve their academic writing.
          </p>
          <div className="space-y-4">
            {features.map((feature) => (
              <div key={feature.title} className="flex items-start gap-3">
                <div className="flex items-center justify-center w-9 h-9 rounded-md bg-primary-foreground/10 shrink-0 mt-0.5">
                  <feature.icon className="h-5 w-5 text-primary-foreground" />
                </div>
                <div>
                  <h3 className="text-sm font-medium text-primary-foreground">{feature.title}</h3>
                  <p className="text-sm text-primary-foreground/70">{feature.description}</p>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>

      <div className="flex-1 flex items-center justify-center p-6 bg-background">
        <Card className="w-full max-w-md">
          <CardHeader>
            <div className="flex items-center gap-2 lg:hidden mb-4">
              <GraduationCap className="h-6 w-6 text-primary" />
              <span className="text-lg font-semibold">RavPaper Tutor</span>
            </div>
            <CardTitle className="text-xl">Create an account</CardTitle>
            <CardDescription>Get started with RavPaper Tutor</CardDescription>
          </CardHeader>
          <CardContent>
            <Form {...form}>
              <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-4">
                <FormField
                  control={form.control}
                  name="fullName"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>Full Name</FormLabel>
                      <FormControl>
                        <Input placeholder="Dr. Jane Smith" data-testid="input-fullname" {...field} />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />
                <FormField
                  control={form.control}
                  name="email"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>Email</FormLabel>
                      <FormControl>
                        <Input type="email" placeholder="you@university.edu" data-testid="input-email" {...field} />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />
                <FormField
                  control={form.control}
                  name="username"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>Username</FormLabel>
                      <FormControl>
                        <Input placeholder="jsmith" data-testid="input-username" {...field} />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />
                <FormField
                  control={form.control}
                  name="password"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>Password</FormLabel>
                      <FormControl>
                        <Input type="password" placeholder="At least 6 characters" data-testid="input-password" {...field} />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />
                <FormField
                  control={form.control}
                  name="confirmPassword"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>Confirm Password</FormLabel>
                      <FormControl>
                        <Input type="password" placeholder="Confirm your password" data-testid="input-confirm-password" {...field} />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />
                <Button
                  type="submit"
                  className="w-full"
                  disabled={registerPending}
                  data-testid="button-register"
                >
                  {registerPending ? "Creating account..." : "Create Account"}
                </Button>
              </form>
            </Form>
            <div className="mt-4 text-center text-sm text-muted-foreground">
              Already have an account?{" "}
              <Link href="/login" className="text-primary font-medium" data-testid="link-login">
                Sign in
              </Link>
            </div>
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

server/replit_integrations/batch/utils.t.content:
import pLimit from "p-limit";
import pRetry from "p-retry";

/**
 * Batch Processing Utilities
 *
 * This module provides a generic batch processing function with built-in
 * rate limiting and automatic retries. Use it for any task that requires
 * processing multiple items through an LLM or external API.
 *
 * USAGE:
 * ```typescript
 * import { batchProcess, isRateLimitError } from "./replit_integrations/batch";
 *
 * const results = await batchProcess(
 *   artworks,
 *   async (artwork) => {
 *     // Your custom LLM logic here
 *     const response = await openai.chat.completions.create({
 *       model: "gpt-5.1",
 *       messages: [{ role: "user", content: `Categorize: ${artwork.name}` }],
 *       response_format: { type: "json_object" },
 *     });
 *     return JSON.parse(response.choices[0]?.message?.content || "{}");
 *   },
 *   { concurrency: 2, retries: 5 }
 * );
 * ```
 */

export interface BatchOptions {
  /** Max concurrent requests (default: 2) */
  concurrency?: number;
  /** Max retry attempts for rate limit errors (default: 7) */
  retries?: number;
  /** Initial retry delay in ms (default: 2000) */
  minTimeout?: number;
  /** Max retry delay in ms (default: 128000) */
  maxTimeout?: number;
  /** Callback for progress updates */
  onProgress?: (completed: number, total: number, item: unknown) => void;
}

/**
 * Check if an error is a rate limit or quota violation.
 * Use this in custom error handling if needed.
 */
export function isRateLimitError(error: unknown): boolean {
  const errorMsg = error instanceof Error ? error.message : String(error);
  return (
    errorMsg.includes("429") ||
    errorMsg.includes("RATELIMIT_EXCEEDED") ||
    errorMsg.toLowerCase().includes("quota") ||
    errorMsg.toLowerCase().includes("rate limit")
  );
}

/**
 * Process items in batches with rate limiting and automatic retries.
 *
 * @param items - Array of items to process
 * @param processor - Async function to process each item (write your LLM logic here)
 * @param options - Concurrency and retry settings
 * @returns Promise resolving to array of results in the same order as input
 *
 * @example
 * // Process CSV artwork data with custom categorization
 * const categorized = await batchProcess(
 *   csvRows,
 *   async (row) => {
 *     const response = await openai.chat.completions.create({
 *       model: "gpt-5.1", // the newest OpenAI model
 *       messages: [{ role: "user", content: `Categorize artwork: ${row.name}` }],
 *       response_format: { type: "json_object" },
 *     });
 *     return { ...row, category: JSON.parse(response.choices[0]?.message?.content || "{}") };
 *   }
 * );
 */
export async function batchProcess<T, R>(
  items: T[],
  processor: (item: T, index: number) => Promise<R>,
  options: BatchOptions = {}
): Promise<R[]> {
  const {
    concurrency = 2,
    retries = 7,
    minTimeout = 2000,
    maxTimeout = 128000,
    onProgress,
  } = options;

  const limit = pLimit(concurrency);
  let completed = 0;

  const promises = items.map((item, index) =>
    limit(() =>
      pRetry(
        async () => {
          try {
            const result = await processor(item, index);
            completed++;
            onProgress?.(completed, items.length, item);
            return result;
          } catch (error: unknown) {
            if (isRateLimitError(error)) {
              throw error; // Rethrow to trigger p-retry
            }
            // For non-rate-limit errors, abort immediately
            throw new pRetry.AbortError(
              error instanceof Error ? error : new Error(String(error))
            );
          }
        },
        { retries, minTimeout, maxTimeout, factor: 2 }
      )
    )
  );

  return Promise.all(promises);
}

/**
 * Process items sequentially with SSE progress streaming.
 * Use this when you need real-time progress updates to the client.
 *
 * @param items - Array of items to process
 * @param processor - Async function to process each item
 * @param sendEvent - Function to send SSE events to the client
 * @param options - Retry settings (concurrency is always 1 for sequential)
 */
export async function batchProcessWithSSE<T, R>(
  items: T[],
  processor: (item: T, index: number) => Promise<R>,
  sendEvent: (event: { type: string; [key: string]: unknown }) => void,
  options: Omit<BatchOptions, "concurrency" | "onProgress"> = {}
): Promise<R[]> {
  const { retries = 5, minTimeout = 1000, maxTimeout = 15000 } = options;

  sendEvent({ type: "started", total: items.length });

  const results: R[] = [];
  let errors = 0;

  for (let index = 0; index < items.length; index++) {
    const item = items[index];
    sendEvent({ type: "processing", index, item });

    try {
      const result = await pRetry(
        () => processor(item, index),
        {
          retries,
          minTimeout,
          maxTimeout,
          factor: 2,
          onFailedAttempt: (error) => {
            if (!isRateLimitError(error)) {
              throw new pRetry.AbortError(
                error instanceof Error ? error : new Error(String(error))
              );
            }
          },
        }
      );
      results.push(result);
      sendEvent({ type: "progress", index, result });
    } catch (error) {
      errors++;
      results.push(undefined as R); // Placeholder for failed items
      sendEvent({
        type: "progress",
        index,
        error: error instanceof Error ? error.message : "Processing failed",
      });
    }
  }

  sendEvent({ type: "complete", processed: items.length, errors });
  return results;
}

client/src/pages/defense.tsx.content:
import { useState } from "react";
import { useQuery, useMutation } from "@tanstack/react-query";
import { useParams, Link } from "wouter";
import { Shield, ArrowLeft, ChevronLeft, ChevronRight, Send, CheckCircle2, AlertCircle } from "lucide-react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { Skeleton } from "@/components/ui/skeleton";
import { Progress } from "@/components/ui/progress";
import { Separator } from "@/components/ui/separator";
import { useToast } from "@/hooks/use-toast";
import { authQueryFn, authFetch } from "@/lib/auth";
import type { Document } from "@shared/schema";

function getScoreColor(score: number): string {
  if (score >= 80) return "text-green-600 dark:text-green-400";
  if (score >= 50) return "text-yellow-600 dark:text-yellow-400";
  return "text-red-600 dark:text-red-400";
}

function getDifficultyColor(difficulty: string): string {
  switch (difficulty?.toLowerCase()) {
    case "hard": return "bg-red-100 dark:bg-red-900/30 text-red-800 dark:text-red-300";
    case "medium": return "bg-yellow-100 dark:bg-yellow-900/30 text-yellow-800 dark:text-yellow-300";
    default: return "bg-green-100 dark:bg-green-900/30 text-green-800 dark:text-green-300";
  }
}

export default function DefensePage() {
  const params = useParams<{ documentId: string }>();
  const { toast } = useToast();
  const documentId = params.documentId;

  const [session, setSession] = useState<any>(null);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [answer, setAnswer] = useState("");
  const [answers, setAnswers] = useState<Record<number, any>>({});

  const { data: document, isLoading: docLoading } = useQuery<Document>({
    queryKey: ["/api/documents", documentId],
    queryFn: authQueryFn,
    enabled: !!documentId,
  });

  const startMutation = useMutation({
    mutationFn: async () => {
      const res = await authFetch(`/api/analysis/defense/${documentId}`, { method: "POST" });
      if (!res.ok) {
        const err = await res.json().catch(() => ({ error: res.statusText }));
        throw new Error(err.error || "Failed to start defense simulation");
      }
      return res.json();
    },
    onSuccess: (data) => {
      setSession(data);
      setCurrentIndex(0);
      setAnswer("");
      setAnswers({});
    },
    onError: (error: any) => {
      toast({ title: "Failed to Start", description: error.message, variant: "destructive" });
    },
  });

  const submitMutation = useMutation({
    mutationFn: async () => {
      const res = await authFetch(`/api/analysis/defense/${session.id}/answer`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ questionIndex: currentIndex, answer }),
      });
      if (!res.ok) {
        const err = await res.json().catch(() => ({ error: res.statusText }));
        throw new Error(err.error || "Failed to submit answer");
      }
      return res.json();
    },
    onSuccess: (data) => {
      setAnswers((prev) => ({ ...prev, [currentIndex]: data }));
      setAnswer("");
    },
    onError: (error: any) => {
      toast({ title: "Submission Failed", description: error.message, variant: "destructive" });
    },
  });

  if (docLoading) {
    return (
      <div className="p-6 space-y-4">
        <Skeleton className="h-8 w-64" />
        <Skeleton className="h-64 w-full" />
      </div>
    );
  }

  const questions: any[] = session?.questions || [];
  const currentQuestion = questions[currentIndex];
  const currentAnswer = answers[currentIndex];
  const allAnswered = questions.length > 0 && Object.keys(answers).length >= questions.length;

  const totalScore = Object.values(answers).reduce(
    (sum: number, a: any) => sum + (a?.evaluation?.score || 0),
    0
  );
  const avgScore = Object.keys(answers).length > 0
    ? Math.round(totalScore / Object.keys(answers).length)
    : 0;

  return (
    <div className="p-6 space-y-6" data-testid="page-defense">
      <div className="flex items-center gap-3 flex-wrap">
        <Button variant="ghost" size="icon" asChild>
          <Link href={`/documents/${documentId}`} data-testid="link-back-document">
            <ArrowLeft className="h-4 w-4" />
          </Link>
        </Button>
        <div>
          <h1 className="text-2xl font-bold" data-testid="text-defense-title">Defense Simulation</h1>
          {document && <p className="text-muted-foreground">{document.title}</p>}
        </div>
      </div>

      {!session && (
        <Card>
          <CardContent className="text-center py-16">
            <Shield className="h-16 w-16 mx-auto text-primary mb-4" />
            <h3 className="text-xl font-bold mb-2">Dissertation Defense Simulator</h3>
            <p className="text-muted-foreground mb-6 max-w-md mx-auto">
              Practice defending your research with AI-generated questions tailored to your document content.
            </p>
            <Button
              onClick={() => startMutation.mutate()}
              disabled={startMutation.isPending}
              data-testid="button-start-defense"
            >
              {startMutation.isPending ? "Generating Questions..." : "Start Defense Simulation"}
            </Button>
          </CardContent>
        </Card>
      )}

      {session && questions.length > 0 && (
        <>
          <div className="flex items-center justify-between gap-4 flex-wrap">
            <p className="text-sm text-muted-foreground">
              Question {currentIndex + 1} of {questions.length}
            </p>
            <Progress value={((Object.keys(answers).length) / questions.length) * 100} className="h-2 flex-1 max-w-xs" />
          </div>

          <Card>
            <CardHeader>
              <div className="flex items-center gap-2 flex-wrap">
                {currentQuestion.category && (
                  <Badge variant="outline">{currentQuestion.category}</Badge>
                )}
                {currentQuestion.difficulty && (
                  <Badge className={getDifficultyColor(currentQuestion.difficulty)}>
                    {currentQuestion.difficulty}
                  </Badge>
                )}
              </div>
              <CardTitle className="text-lg mt-2" data-testid="text-question">
                {currentQuestion.question}
              </CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              {!currentAnswer ? (
                <>
                  <Textarea
                    placeholder="Type your answer here..."
                    value={answer}
                    onChange={(e) => setAnswer(e.target.value)}
                    className="min-h-[150px] resize-y"
                    data-testid="textarea-answer"
                  />
                  <Button
                    onClick={() => submitMutation.mutate()}
                    disabled={submitMutation.isPending || !answer.trim()}
                    className="w-full"
                    data-testid="button-submit-answer"
                  >
                    {submitMutation.isPending ? "Evaluating..." : (
                      <>
                        <Send className="h-4 w-4" />
                        Submit Answer
                      </>
                    )}
                  </Button>
                </>
              ) : (
                <div className="space-y-4">
                  <div className="p-4 rounded-md bg-muted/50">
                    <p className="text-sm text-muted-foreground mb-1">Your Answer:</p>
                    <p className="text-sm">{currentAnswer.evaluation ? answers[currentIndex]?.evaluation?.answer || answer : answer}</p>
                  </div>

                  <Separator />

                  <div className="flex items-center justify-between gap-2 flex-wrap">
                    <span className="text-sm font-medium">Score:</span>
                    <span className={`text-2xl font-bold ${getScoreColor(currentAnswer.evaluation?.score || 0)}`} data-testid="text-answer-score">
                      {currentAnswer.evaluation?.score || 0}%
                    </span>
                  </div>
                  <Progress value={currentAnswer.evaluation?.score || 0} className="h-2" />

                  {currentAnswer.evaluation?.feedback && (
                    <div>
                      <p className="text-sm font-medium mb-1">Feedback:</p>
                      <p className="text-sm text-muted-foreground" data-testid="text-feedback">{currentAnswer.evaluation.feedback}</p>
                    </div>
                  )}

                  {currentAnswer.evaluation?.strengths && currentAnswer.evaluation.strengths.length > 0 && (
                    <div>
                      <p className="text-sm font-medium mb-1 text-green-600 dark:text-green-400">Strengths:</p>
                      <ul className="list-disc list-inside space-y-1">
                        {currentAnswer.evaluation.strengths.map((s: string, i: number) => (
                          <li key={i} className="text-sm text-muted-foreground">{s}</li>
                        ))}
                      </ul>
                    </div>
                  )}

                  {currentAnswer.evaluation?.weaknesses && currentAnswer.evaluation.weaknesses.length > 0 && (
                    <div>
                      <p className="text-sm font-medium mb-1 text-red-600 dark:text-red-400">Areas for Improvement:</p>
                      <ul className="list-disc list-inside space-y-1">
                        {currentAnswer.evaluation.weaknesses.map((w: string, i: number) => (
                          <li key={i} className="text-sm text-muted-foreground">{w}</li>
                        ))}
                      </ul>
                    </div>
                  )}
                </div>
              )}
            </CardContent>
          </Card>

          <div className="flex items-center justify-between gap-2 flex-wrap">
            <Button
              variant="outline"
              onClick={() => setCurrentIndex((i) => Math.max(0, i - 1))}
              disabled={currentIndex === 0}
              data-testid="button-prev-question"
            >
              <ChevronLeft className="h-4 w-4" />
              Previous
            </Button>
            <Button
              variant="outline"
              onClick={() => setCurrentIndex((i) => Math.min(questions.length - 1, i + 1))}
              disabled={currentIndex >= questions.length - 1}
              data-testid="button-next-question"
            >
              Next
              <ChevronRight className="h-4 w-4" />
            </Button>
          </div>

          {allAnswered && (
            <Card>
              <CardHeader>
                <div className="flex items-center gap-2">
                  <CheckCircle2 className="h-5 w-5 text-green-600 dark:text-green-400" />
                  <CardTitle className="text-lg">Defense Complete</CardTitle>
                </div>
                <CardDescription>You have answered all {questions.length} questions</CardDescription>
              </CardHeader>
              <CardContent>
                <div className="flex items-center justify-between gap-2 mb-3 flex-wrap">
                  <span className="text-sm font-medium">Overall Defense Score:</span>
                  <span className={`text-3xl font-bold ${getScoreColor(avgScore)}`} data-testid="text-overall-defense-score">
                    {avgScore}%
                  </span>
                </div>
                <Progress value={avgScore} className="h-3" />
              </CardContent>
            </Card>
          )}
        </>
      )}
    </div>
  );
}

client/src/components/ui/toggle-group.ts.content:
"use client"

import * as React from "react"
import * as ToggleGroupPrimitive from "@radix-ui/react-toggle-group"
import { type VariantProps } from "class-variance-authority"

import { cn } from "@/lib/utils"
import { toggleVariants } from "@/components/ui/toggle"

const ToggleGroupContext = React.createContext<
  VariantProps<typeof toggleVariants>
>({
  size: "default",
  variant: "default",
})

const ToggleGroup = React.forwardRef<
  React.ElementRef<typeof ToggleGroupPrimitive.Root>,
  React.ComponentPropsWithoutRef<typeof ToggleGroupPrimitive.Root> &
    VariantProps<typeof toggleVariants>
>(({ className, variant, size, children, ...props }, ref) => (
  <ToggleGroupPrimitive.Root
    ref={ref}
    className={cn("flex items-center justify-center gap-1", className)}
    {...props}
  >
    <ToggleGroupContext.Provider value={{ variant, size }}>
      {children}
    </ToggleGroupContext.Provider>
  </ToggleGroupPrimitive.Root>
))

ToggleGroup.displayName = ToggleGroupPrimitive.Root.displayName

const ToggleGroupItem = React.forwardRef<
  React.ElementRef<typeof ToggleGroupPrimitive.Item>,
  React.ComponentPropsWithoutRef<typeof ToggleGroupPrimitive.Item> &
    VariantProps<typeof toggleVariants>
>(({ className, children, variant, size, ...props }, ref) => {
  const context = React.useContext(ToggleGroupContext)

  return (
    <ToggleGroupPrimitive.Item
      ref={ref}
      className={cn(
        toggleVariants({
          variant: context.variant || variant,
          size: context.size || size,
        }),
        className
      )}
      {...props}
    >
      {children}
    </ToggleGroupPrimitive.Item>
  )
})

ToggleGroupItem.displayName = ToggleGroupPrimitive.Item.displayName

export { ToggleGroup, ToggleGroupItem }

